    ]
  },
  {
    "alert_id": "ALERT_002",
    "title": "No clinician assessment or plan documented",
    "message": "Guidelines require serum creatinine and eGFR monitoring every 12 months for TDF-experienced patients. This patient's latest eGFR is 52 mL/min/1.73m², which per guidelines warrants substitution of TDF. No assessment or plan was documented for this visit, meaning the significant renal decline and proteinuria have not been addressed. Additionally, no alternative regimen plan, renal referral, or medication review (including ibuprofen counselling) has been recorded.",
    "issue_type": "plan_review",
    "severity": "high",
    "recommended_action": "Document assessment of declining renal function. Plan TDF substitution per guidelines, counsel on NSAID avoidance, and arrange renal evaluation for proteinuria.",
    "citations": [
      {"page_number": 27, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"},
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"}
    ]
  },
  {
    "alert_id": "ALERT_003",
    "title": "Ibuprofen use compounding TDF renal risk",
    "message": "The patient takes ibuprofen 400 mg 2–3 times weekly for headaches. NSAIDs can reduce renal perfusion via prostaglandin inhibition, worsening renal function. Combined with TDF, which is nephrotoxic, and an eGFR already at 52 mL/min/1.73m², this compounds the risk of further renal decline. The proteinuria detected on urinalysis may reflect ongoing renal tubular injury from combined TDF and NSAID exposure.",
    "issue_type": "compounding_risk",
    "severity": "moderate",
    "recommended_action": "Counsel patient to discontinue or minimise ibuprofen use. Consider alternative headache management such as paracetamol. Monitor renal function closely.",
    "citations": []
  }
